import { cache } from "react";

import type { PaginatedResponse, Todo } from "@repo/shared/types";

// Reads of the public todos API, for a client with no signed-in user.
//
// Generated by grit with --public, and not overwritten when the resource is
// regenerated: the Go side's allowlist is yours to edit, and this file is typed
// against it.
//
// These call /public/todos, not the authenticated routes the hooks in
// hooks/use-todos.ts call. The authenticated ones answer 401
// without a session, which is correct for the admin panel and useless here.

const API_URL = (
  process.env.API_INTERNAL_URL ||
  process.env.NEXT_PUBLIC_API_URL ||
  "http://localhost:8080"
).replace(/\/+$/, "");

// Publishable by design: it reaches the read-only public endpoints and nothing
// else, which is why the seeder writes it as NEXT_PUBLIC_.
const API_KEY = process.env.NEXT_PUBLIC_API_KEY ?? "";

// Pages revalidate on this interval, so an edit in the admin shows within a
// minute without a deploy.
const REVALIDATE_SECONDS = 60;

// PublicTodo is the published shape: the allowlist in
// internal/handlers/todo_public.go, not the model. Add a field
// there and add it here.
export interface PublicTodo {
  id: string;
  title: string;
  completed: boolean;
}

export type PublicTodoPage = {
  data: PublicTodo[];
  meta: PaginatedResponse<PublicTodo>["meta"] | undefined;
};

async function publicGet<T>(
  path: string,
): Promise<{ status: number; body: T | null }> {
  try {
    const res = await fetch(API_URL + path, {
      headers: API_KEY ? { "X-API-Key": API_KEY } : {},
      next: { revalidate: REVALIDATE_SECONDS },
    });
    if (!res.ok) return { status: res.status, body: null };
    return { status: res.status, body: (await res.json()) as T };
  } catch {
    // The API is unreachable, as it is while a production build runs in CI. A
    // list renders empty and fills in on the next request rather than failing
    // the build.
    return { status: 0, body: null };
  }
}

// One page of todos. Every search, sort, filter and range the
// public handler allows is a query parameter; anything it does not allow is
// ignored rather than rejected.
export const getPublicTodos = cache(
  async (
    params: Record<string, string | number | undefined> = {},
  ): Promise<PublicTodoPage> => {
    const query = new URLSearchParams();
    for (const [key, value] of Object.entries(params)) {
      if (value !== undefined && value !== "") query.set(key, String(value));
    }
    const suffix = query.toString() ? "?" + query.toString() : "";
    const { body } = await publicGet<PaginatedResponse<PublicTodo>>(
      "/api/v1/public/todos" + suffix,
    );
    return { data: body?.data ?? [], meta: body?.meta };
  },
);

// One todo by its public key, or null when there is none.
//
// A row that is archived or switched off is a 404 here, the same as one that
// never existed: whether it exists is itself not public. An API that fails is
// an error rather than a missing row, so it is not reported as null.
export const getPublicTodo = cache(
  async (key: string): Promise<PublicTodo | null> => {
    const { status, body } = await publicGet<{ data: PublicTodo }>(
      "/api/v1/public/todos/" + encodeURIComponent(key),
    );
    if (status === 404) return null;
    if (!body)
      throw new Error(
        "the public todo API answered " + (status || "nothing") + " for " + key,
      );
    return body.data;
  },
);
async function postToApi<T, D = unknown>(
  path: string,
  data: D,
): Promise<{ status: number; body: T | null }> {
  try {
    const res = await fetch(`${API_URL}/${path}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...(API_KEY ? { "X-API-KEY": API_KEY } : {}),
      },
      body: JSON.stringify(data),
      next: {
        revalidate: REVALIDATE_SECONDS,
      },
    });
    if (!res.ok) {
      return {
        status: res.status,
        body: null,
      };
    }
    const result = (await res.json()) as T;
    return {
      status: res.status,
      body: result,
    };
  } catch (error) {
    return {
      status: 500,
      body: null,
    };
  }
}

type NewTodo = {
  title: string;
  completed: boolean;
};
type Response = {
  data: NewTodo;
  message: string;
};

export async function createTodo() {
  try {
    const todo = await postToApi<NewTodo, Response>();
  } catch (error) {}
}
